&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Mendiant&lt;div style=&quot;float:right;&quot;&gt;FP 1/3&lt;/div&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Manuel-Des-Pnj-(Contenu).html&quot; title=&quot;Manuel des PNJ (Contenu)&quot;&gt;Manuel des PNJ p. 256&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 135
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Du-Peuple.html&quot; title=&quot;L&amp;#39;homme du peuple&quot;&gt;homme du peuple&lt;/a&gt; 1
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Elfe.html&quot; title=&quot;Elfe (sous-type)&quot;&gt;elfe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Humain.html&quot; title=&quot;Humain (sous-type)&quot;&gt;humain&lt;/a&gt;) de taille M, CN
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +2 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 12, contact 12, pris au d&#233;pourvu 10 (Dex +2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 4 (1d6+1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +2, &lt;b&gt;Vig&lt;/b&gt; +1, &lt;b&gt;Vol&lt;/b&gt; –1 ; +2 contre les enchantements
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Immunit&#233;s&lt;/b&gt; sommeil
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; dague, -1 (1d4–1/19–20)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; L’homme du peuple offre sa mis&#233;rable poign&#233;e de pi&#232;ces de cuivre en &#233;change de sa vie. Si l’interlocuteur refuse, il fond sur lui avec sa dague en hurlant &#224; l’aide.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Statistiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 8, &lt;b&gt;Dex&lt;/b&gt; 14, &lt;b&gt;Con&lt;/b&gt; 13, &lt;b&gt;Int&lt;/b&gt; 11, &lt;b&gt;Sag&lt;/b&gt; 9, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +0 ; &lt;b&gt;BMO&lt;/b&gt; -1 ; &lt;b&gt;DMD&lt;/b&gt; 11
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Endurance.html&quot; title=&quot;Endurance&quot;&gt;Endurance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Bluff)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +4, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; +2, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +5, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (instruments &#224; vent)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, elfe
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; sang elfique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Instrument-De-Musique-(Objet).html&quot; title=&quot;Instrument de musique&quot;&gt;fl&#251;te en bois&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Trousse-De-D&#233;guisement-(Objet).html&quot; title=&quot;Trousse de d&#233;guisement&quot;&gt;trousse de d&#233;guisement&lt;/a&gt;, 203 po
&lt;/div&gt;
&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;Le mendiant a eu une vie difficile. Il peut &#234;tre un mendiant honn&#234;te comme il peut jouer la com&#233;die, se faire passer pour un h&#233;ros de guerre ou d&#233;figur&#233;, pour susciter la piti&#233;.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
